  "test": "import pytest
import pydantic

from langfuse.api.organizations.types.membership_request import MembershipRequest, MembershipRole


def test_user_id_must_be_non_empty():
    # Obtain any valid role value from the enum
    role = list(MembershipRole)[0]
    # Empty user_id should raise a ValidationError
    with pytest.raises(pydantic.ValidationError):
        MembershipRequest(user_id="", role=role)
    # Valid user_id should succeed
    mr = MembershipRequest(user_id="valid-id", role=role)
    assert mr.user_id == "valid-id"
